<?php declare(strict_types=1);require_once __DIR__.'/../includes/auth_check.php';require_once __DIR__.'/../includes/functions.php';$id=0;$editing=false;$record=['category_name'=>'','description'=>''];if($editing){$s=$pdo->prepare('SELECT * FROM categories WHERE category_id=?');$s->execute([$id]);$record=$s->fetch();if(!$record){set_flash('error','Record not found.');redirect('/categories/index.php');}}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){if(!verify_csrf_token($_POST['csrf_token']??null))$error='Session expired. Refresh and try again.';else{$name=trim($_POST['category_name']??'');$other=trim($_POST['description']??'');if($name==='')$error='Name is required.';else{try{if($editing){$s=$pdo->prepare('UPDATE categories SET category_name=?,description=? WHERE category_id=?');$s->execute([$name,$other?:null,$id]);}else{$s=$pdo->prepare('INSERT INTO categories(category_name,description) VALUES(?,?)');$s->execute([$name,$other?:null]);}set_flash('success','Record saved.');redirect('/categories/index.php');}catch(PDOException $e){$error='This name may already exist or the record is linked to another item.';}}}}$pageTitle=$editing?'Edit categorie':'Add categorie';$activePage='categories';require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/navbar.php';?>
